(() => {
  const apply = () => {
    const card = document.querySelector('[data-name="logitech pebble mouse 2 m350s raton bluetooth silencioso"]');
    if (!card) return;
    const link = card.querySelector('.offer-button');
    if (link) link.href = 'https://amzn.to/4r8X1Gw';
    const art = card.querySelector('.product-art');
    if (art) {
      art.style.cssText = 'display:flex;align-items:center;justify-content:center;padding:0;background:#fff;overflow:hidden;';
      art.innerHTML = '<img src="data:image/jpeg;base64," alt="Logitech Pebble Mouse 2 M350s" loading="lazy" style="width:auto;height:auto;max-width:72%;max-height:72%;object-fit:contain;display:block;margin:auto">';
      art.removeAttribute('aria-hidden');
      art.setAttribute('role','img');
      art.setAttribute('aria-label','Logitech Pebble Mouse 2 M350s');
    }
  };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', apply);
  else apply();
})();
